-- Bunny Court replaces the retired Focus audio feature.
-- Content is sourced from Burrow_Bunny_Court_Content_System_v1 (36 cases,
-- 132 questions, 108 privacy-safe verdict templates). Runtime answers remain
-- service-only and are never exposed before both players seal testimony.

create table if not exists public.court_case_definitions (
  case_id text primary key,
  category text not null,
  title text not null,
  card_subtitle text not null,
  eligibility text not null,
  engine text not null,
  access_tier text not null check (access_tier in ('free', 'plus')),
  verdict_method text not null,
  user_value text not null,
  question_count integer not null check (question_count > 0),
  repeatability text not null,
  sensitivity text not null,
  status text not null,
  analysis_logic text not null,
  outcome_keys jsonb not null default '[]'::jsonb,
  scoring_display text,
  result_anatomy text,
  insufficient_evidence_rule text,
  notification_copy jsonb not null default '{}'::jsonb,
  content_version integer not null default 1,
  updated_at timestamptz not null default now()
);

create table if not exists public.court_questions (
  case_id text not null references public.court_case_definitions(case_id) on delete cascade,
  question_number integer not null,
  prompt text not null,
  other_player_prompt text,
  response_type text not null,
  question_class text not null,
  access_tag text,
  options jsonb not null default '[]'::jsonb,
  analysis_dimension text,
  required boolean not null default true,
  interaction_rule text,
  primary key (case_id, question_number)
);

create table if not exists public.court_verdict_templates (
  case_id text not null references public.court_case_definitions(case_id) on delete cascade,
  outcome_key text not null,
  headline text not null,
  what_court_heard text not null,
  verdict text not null,
  court_ordered_move text not null,
  share_text text not null,
  tone_condition text,
  primary key (case_id, outcome_key)
);

create table if not exists public.court_sessions (
  id uuid primary key default gen_random_uuid(),
  pair_low uuid not null references auth.users(id) on delete cascade,
  pair_high uuid not null references auth.users(id) on delete cascade,
  initiator_id uuid not null references auth.users(id) on delete cascade,
  partner_id uuid not null references auth.users(id) on delete cascade,
  case_id text not null references public.court_case_definitions(case_id),
  content_version integer not null default 1,
  content_snapshot jsonb not null default '{}'::jsonb,
  access_tier_snapshot text not null check (access_tier_snapshot in ('free', 'plus')),
  status text not null default 'awaiting_initiator'
    check (status in ('awaiting_initiator','awaiting_partner','processing','ready','completed','declined','expired','cancelled')),
  expires_at timestamptz not null default (now() + interval '7 days'),
  declined_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  verdict_ready_at timestamptz,
  completed_at timestamptz,
  check (pair_low < pair_high),
  check (initiator_id <> partner_id),
  check (initiator_id in (pair_low, pair_high)),
  check (partner_id in (pair_low, pair_high))
);
create unique index if not exists court_one_open_case_per_pair
  on public.court_sessions(pair_low, pair_high)
  where status in ('awaiting_initiator','awaiting_partner','processing','ready');
create index if not exists court_sessions_member_updated_idx
  on public.court_sessions(pair_low, pair_high, updated_at desc);

create table if not exists public.court_submissions (
  session_id uuid not null references public.court_sessions(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  answers jsonb not null,
  submitted_at timestamptz not null default now(),
  primary key (session_id, user_id)
);

create table if not exists public.court_verdict_jobs (
  session_id uuid primary key references public.court_sessions(id) on delete cascade,
  status text not null default 'pending' check (status in ('pending','processing','retry','complete','failed')),
  attempts integer not null default 0,
  next_attempt_at timestamptz not null default now(),
  locked_at timestamptz,
  last_error text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.court_verdicts (
  session_id uuid primary key references public.court_sessions(id) on delete cascade,
  case_id text not null references public.court_case_definitions(case_id),
  engine text not null,
  analysis_method text not null,
  outcome_key text not null,
  headline text not null,
  what_court_heard text not null,
  verdict text not null,
  court_ordered_move text not null,
  share_text text not null,
  safety_state text not null default 'safe',
  model text,
  created_at timestamptz not null default now()
);

alter table public.notification_outbox add column if not exists event_type text not null default 'partner_reflect';
alter table public.notification_outbox add column if not exists payload jsonb not null default '{}'::jsonb;

alter table public.court_case_definitions enable row level security;
alter table public.court_questions enable row level security;
alter table public.court_verdict_templates enable row level security;
alter table public.court_sessions enable row level security;
alter table public.court_submissions enable row level security;
alter table public.court_verdict_jobs enable row level security;
alter table public.court_verdicts enable row level security;
revoke all on public.court_case_definitions, public.court_questions, public.court_verdict_templates,
  public.court_sessions, public.court_submissions, public.court_verdict_jobs, public.court_verdicts
  from public, anon, authenticated;
grant all on public.court_case_definitions, public.court_questions, public.court_verdict_templates,
  public.court_sessions, public.court_submissions, public.court_verdict_jobs, public.court_verdicts
  to service_role;

create or replace function public.broadcast_court_session_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform realtime.send(
    jsonb_build_object('session_id', new.id, 'changed_at', now()),
    'court_changed',
    'pairing:' || new.initiator_id::text,
    true
  );
  perform realtime.send(
    jsonb_build_object('session_id', new.id, 'changed_at', now()),
    'court_changed',
    'pairing:' || new.partner_id::text,
    true
  );
  return new;
end;
$$;

drop trigger if exists court_session_change_broadcast on public.court_sessions;
create trigger court_session_change_broadcast
after insert or update of status, updated_at on public.court_sessions
for each row execute function public.broadcast_court_session_change();

insert into public.court_case_definitions (
  case_id, category, title, card_subtitle, eligibility, engine, access_tier,
  verdict_method, user_value, question_count, repeatability, sensitivity, status,
  analysis_logic, outcome_keys, scoring_display, result_anatomy,
  insufficient_evidence_rule, notification_copy
) values
('LOVE-01', 'Love Court', 'WHO''S MORE DOWN BAD?', 'Present the evidence. Pretending to be chill is admissible, but suspicious.', 'Partner only', 'PLAYFUL_COMPARE', 'plus', 'AI-ASSISTED', 'Compare visible and quiet signs of romantic attachment without ranking love.', 4, 'Monthly', 'Low', 'Launch', 'Award points only for observable attachment behaviors. Compare thought frequency, initiation, memory and effort separately. Never conclude that one person loves more. Use a tie when total scores differ by 0-1; otherwise award a playful behavior-specific crown.', '["balanced","initiator_leads","detail_leads"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for WHO''S MORE DOWN BAD?. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on WHO''S MORE DOWN BAD?.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb),
('LOVE-02', 'Love Court', 'THE SECRET SOFTIE CASE', 'Who acts chill but is secretly made of feelings?', 'Partner only', 'PLAYFUL_COMPARE', 'plus', 'AI-ASSISTED', 'Reveal understated affection and emotional softness.', 4, 'Quarterly', 'Low', 'Launch', 'Compare keepsakes, verbal affection and disclosed soft spots. Reward honesty, not emotional intensity. If answers reveal different styles, name both styles rather than selecting a loser.', '["mutual","one_exposed","different_styles"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE SECRET SOFTIE CASE. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE SECRET SOFTIE CASE.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb),
('LOVE-03', 'Love Court', 'THE FLIRTING RIGHTS TRIAL', 'Who has game, and who survives entirely on being cute?', 'Partner only', 'PLAYFUL_COMPARE', 'plus', 'AI-ASSISTED', 'Reveal flirting styles and what actually lands.', 4, 'Monthly', 'Low', 'Launch', 'Score initiation and mutual preference fit. Judge the style, not attractiveness. Never shame low initiation. Flag explicit text for partner-only mature handling and do not place it in share copy.', '["mutual_menace","licensed_flirt","style_mismatch"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE FLIRTING RIGHTS TRIAL. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE FLIRTING RIGHTS TRIAL.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb),
('LOVE-04', 'Love Court', 'THE AFFECTION INITIATOR', 'Who starts the little things that keep love visible?', 'Partner only', 'PLAYFUL_COMPARE', 'free', 'DETERMINISTIC RULES', 'Compare initiation across messages, touch, plans and appreciation.', 4, 'Monthly', 'Low', 'Launch', 'Compare channels and unmet preferences. Do not treat frequency as love. A matched desired channel becomes the Court-Ordered Move; a clear imbalance produces a gentle turn-taking experiment.', '["balanced","imbalance","missed_channel"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE AFFECTION INITIATOR. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE AFFECTION INITIATOR.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb),
('LOVE-05', 'Love Court', 'THE COMPLIMENT THAT HITS', 'Find the words that actually stay with them.', 'Partner only', 'PREDICT_AND_REVEAL', 'plus', 'AI-ASSISTED', 'Learn what kind of appreciation feels most meaningful.', 4, 'Quarterly', 'Low', 'Launch', 'Compare each self-answer with the other player''s prediction. Weight the open-text semantic match as insight, not score. High match celebrates attunement; mismatch reveals a usable preference without blame.', '["high_match","partial","surprise"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE COMPLIMENT THAT HITS. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE COMPLIMENT THAT HITS.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb),
('LOVE-06', 'Love Court', 'THE ROMANTIC MEMORY TRIAL', 'Two witnesses. One relationship story. Very selective evidence.', 'Partner only', 'MEMORY_COMPARE', 'plus', 'AI-ASSISTED', 'Compare how both people remember meaningful romantic moments.', 4, 'Quarterly', 'Low', 'Launch', 'Use semantic overlap to identify shared memory, complementary detail or different memory. Never mark a person wrong for remembering differently. Do not expose intimate details in social share text.', '["same_memory","different_memory","ordinary_wins"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE ROMANTIC MEMORY TRIAL. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE ROMANTIC MEMORY TRIAL.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb),
('CLOSE-01', 'Closeness Court', 'THE TINY DETAIL TROPHY', 'Who notices the little things most people miss?', 'All relationships', 'PREDICT_AND_REVEAL', 'plus', 'AI-ASSISTED', 'Test awareness of current everyday preferences and context.', 4, 'Monthly', 'Low', 'Launch', 'Compare predictions with self-reports. Score exact category matches and semantic proximity. Reward specific attention; never convert misses into a relationship score.', '["high_match","split","surprise"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE TINY DETAIL TROPHY. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE TINY DETAIL TROPHY.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb),
('CLOSE-02', 'Closeness Court', 'WHO KNOWS WHO BEST?', 'Confidence is admissible. Guessing is not.', 'All relationships', 'PREDICT_AND_REVEAL', 'free', 'DETERMINISTIC RULES', 'Test knowledge across preferences, habits and current needs.', 4, 'Monthly', 'Low', 'Launch', 'One point for each exact prediction. Also report the most useful miss. Do not turn the total into closeness, compatibility or relationship health.', '["high","mixed","low"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for WHO KNOWS WHO BEST?. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on WHO KNOWS WHO BEST?.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb),
('CLOSE-03', 'Closeness Court', 'THE MEMORY MATCH', 'Describe the same moment without comparing notes.', 'All relationships', 'MEMORY_COMPARE', 'plus', 'AI-ASSISTED', 'Reveal shared and complementary memory details.', 4, 'Quarterly', 'Low', 'Launch', 'Compare whether players selected the same memory, then semantic overlap in sequence, detail and meaning. Different memories are valid. Never adjudicate factual disputes involving serious harm.', '["strong_match","complementary","different"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE MEMORY MATCH. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE MEMORY MATCH.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb),
('CLOSE-04', 'Closeness Court', 'THE CURRENT OBSESSION CASE', 'Can they identify what has taken over your brain lately?', 'All relationships', 'PREDICT_AND_REVEAL', 'plus', 'AI-ASSISTED', 'Surface current interests without mistaking one activity for a lasting identity.', 4, 'Monthly', 'Low', 'Launch', 'Require the self-report to confirm current interest. Compare type, intensity, next step and semantic topic match. Do not label it a lasting hobby unless continuity is explicit.', '["nailed","topic_only","surprise"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE CURRENT OBSESSION CASE. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE CURRENT OBSESSION CASE.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb),
('CLOSE-05', 'Closeness Court', 'THE MOOD DECODER', 'Can they read your weather without inventing a storm?', 'All relationships', 'PREDICT_AND_REVEAL', 'plus', 'AI-ASSISTED', 'Improve recognition of current mood signals and support preferences.', 4, 'Monthly', 'Medium', 'Launch', 'Compare self-described signal, observer prediction and support preference. Never diagnose mood or infer hidden intent. Focus on preventing one likely misunderstanding.', '["aligned","signal_match","misread"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE MOOD DECODER. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE MOOD DECODER.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb),
('CLOSE-06', 'Closeness Court', 'PREDICT THEIR PICK', 'Choose for them. Confidence will be documented.', 'All relationships', 'PREDICT_AND_REVEAL', 'free', 'DETERMINISTIC RULES', 'Playfully test current preferences through realistic choices.', 4, 'Weekly', 'Low', 'Launch', 'One point per exact match. Highlight the most actionable matched preference and the funniest miss. Rotate option sets to preserve repeatability.', '["perfect","good","chaos"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for PREDICT THEIR PICK. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on PREDICT THEIR PICK.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb),
('LIFE-01', 'Life Court', 'THE TAKEOUT TRIBUNAL', 'Cravings will testify. So will the budget.', 'All relationships; local or remote meal', 'FAIR_DECISION', 'free', 'DETERMINISTIC RULES', 'Choose a meal using appetite, energy, budget and vetoes.', 4, 'Weekly', 'Low', 'Launch', 'Eliminate vetoed options, then maximize craving overlap while respecting the lower budget and lower effort capacity. If no overlap, choose a two-part order or alternating pick.', '["clear","split","low_energy"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE TAKEOUT TRIBUNAL. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE TAKEOUT TRIBUNAL.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb),
('LIFE-02', 'Life Court', 'THE WEEKEND DRAFT', 'Build a weekend both nervous systems can afford.', 'All relationships', 'FAIR_DECISION', 'free', 'DETERMINISTIC RULES', 'Balance rest, adventure, chores and social energy.', 4, 'Weekly', 'Low', 'Launch', 'Honor both must-haves, the lower energy level and all hard vetoes. Build one anchor plan plus protected recovery time unless both want more structure.', '["aligned","rest_adventure","productive_cozy"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE WEEKEND DRAFT. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE WEEKEND DRAFT.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb),
('LIFE-03', 'Life Court', 'THE CALL-TIME NEGOTIATION', 'Find a call that fits real life, not imaginary free time.', 'Long-distance or busy pairs', 'FAIR_DECISION', 'free', 'DETERMINISTIC RULES', 'Choose timing, length and format for the next connection.', 4, 'Weekly', 'Low', 'Launch', 'Find overlapping windows and choose the shorter duration when energy differs. If no live overlap exists, select an asynchronous format. Never imply lower availability means lower care.', '["overlap","format_bridge","energy_gap"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE CALL-TIME NEGOTIATION. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE CALL-TIME NEGOTIATION.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb),
('LIFE-04', 'Life Court', 'THE NEXT VISIT FILE', 'Protect the reunion from becoming an unpaid event-planning job.', 'Long-distance pairs', 'FAIR_DECISION', 'free', 'DETERMINISTIC RULES', 'Set priorities and divide planning for an upcoming visit.', 4, 'Per visit', 'Medium', 'Launch', 'Build a visit plan around both priorities, the slower preferred pace and explicit disappointment risks. Assign tasks based on volunteered ownership; never infer financial ability.', '["aligned","pace_gap","priority_gap"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE NEXT VISIT FILE. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE NEXT VISIT FILE.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb),
('LIFE-05', 'Life Court', 'THE SHOW CUSTODY BATTLE', 'One screen. Two moods. Limited veto power.', 'All relationships', 'FAIR_DECISION', 'free', 'DETERMINISTIC RULES', 'Choose shared entertainment quickly and fairly.', 4, 'Weekly', 'Low', 'Launch', 'Remove vetoes, match lower attention capacity, then give final selection to the person who did not pick last. If fairness is unknown, offer a three-option shortlist.', '["clear","picker","attention_gap"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for THE SHOW CUSTODY BATTLE. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE SHOW CUSTODY BATTLE.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb),
('LIFE-06', 'Life Court', 'WHO PLANS THE NEXT THING?', 'The clipboard cannot belong to one person forever.', 'All relationships', 'FAIR_DECISION', 'free', 'DETERMINISTIC RULES', 'Distribute planning responsibility for the next shared activity.', 4, 'Monthly', 'Low', 'Launch', 'Prioritize fairness history and current capacity. Assign discrete roles from volunteered ownership. Never punish the lower-energy person; use a lighter role or future turn.', '["clear_owner","split_roles","low_capacity"]'::jsonb, 'Internal case-specific score allowed; never a relationship score', 'What the Court Heard + Final Verdict + Court-Ordered Move', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A case has been filed.","inviteBody":"Your person submitted their testimony for WHO PLANS THE NEXT THING?. The court needs your side.","inviteCta":"Testify Now","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on WHO PLANS THE NEXT THING?.","readyCta":"Hear the Verdict","privacyNote":"No peeking. Your answers stay sealed until both sides finish."}'::jsonb),
('MIDDLE-01', 'Meet in the Middle', 'THE REPLY-TIME CASE', 'Less decoding. More realistic expectations.', 'All relationships', 'COMMON_GROUND', 'free', 'DETERMINISTIC RULES', 'Align response expectations without measuring care by speed.', 4, 'As needed', 'Medium', 'Launch', 'Identify each comfort window, reasons and smallest realistic reassurance. Never interpret slow replies as avoidance or lack of care. Output the smallest mutual rule both explicitly support.', '["aligned","bridge","no_overlap"]'::jsonb, 'No score shown', 'What You Need + What They Need + Where You Meet + Try This', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A little middle ground?","inviteBody":"Your person invited you to work through the reply-time case together.","inviteCta":"Add Your Side","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on THE REPLY-TIME CASE.","readyCta":"Hear the Verdict","privacyNote":"No pressure to agree instantly. Start with your honest side."}'::jsonb),
('MIDDLE-02', 'Meet in the Middle', 'TALK NOW OR LATER?', 'Find the pause that calms things without feeling like disappearance.', 'All relationships', 'COMMON_GROUND', 'free', 'DETERMINISTIC RULES', 'Agree on conflict timing and safe cooling-off signals.', 4, 'As needed', 'Medium', 'Launch', 'Use the longer minimum pause required for regulation, but require a return signal within the shorter person''s safety window. Do not mediate threats, abuse or coercion; route those cases out.', '["aligned","pace_gap","too_hot"]'::jsonb, 'No score shown', 'What You Need + What They Need + Where You Meet + Try This', 'Return clarify/no verdict when required answers are missing or safety gate triggers.', '{"inviteTitle":"A little middle ground?","inviteBody":"Your person invited you to work through talk now or later? together.","inviteCta":"Add Your Side","readyTitle":"The verdict is ready.","readyBody":"Both sides are in. Bunny Judge has ruled on TALK NOW OR LATER?.","readyCta":"Hear the Verdict","privacyNote":"No pressure to agree instantly. Start with your honest side."}'::jsonb),
