on conflict (case_id, outcome_key) do update set
  headline = excluded.headline, what_court_heard = excluded.what_court_heard,
  verdict = excluded.verdict, court_ordered_move = excluded.court_ordered_move,
  share_text = excluded.share_text, tone_condition = excluded.tone_condition;

create or replace function public.cancel_open_court_cases_after_unpair()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.court_sessions
     set status = 'cancelled', updated_at = now()
   where pair_low = least(old.user_id, old.partner_user_id)
     and pair_high = greatest(old.user_id, old.partner_user_id)
     and status in ('awaiting_initiator','awaiting_partner','processing','ready');
  return old;
end;
$$;
drop trigger if exists court_cancel_after_unpair on public.pairings;
create trigger court_cancel_after_unpair after delete on public.pairings
for each row execute function public.cancel_open_court_cases_after_unpair();

-- Focus is no longer written. Historical reward ledger rows remain so users
-- never lose previously earned Clovers. Runtime tables can be dropped safely.
drop table if exists public.focus_sessions;
drop table if exists public.user_focus_progress;
